private StoredResponse approveAllergenRisk(String batchKey, String actor, ApprovalRole role, ApproveRequest req) {
    BatchRepository.RiskRow risk = repo.findActiveRisk(batchKey)
            .orElseThrow(() -> ApiException.conflict("批次状态 ALLERGEN_RISK 但缺少风险记录: " + batchKey));
    List<String> required = repo.findRequiredTests(batchKey);
    CompositionRow current = repo.findLatestComposition(batchKey).orElseThrow(...);
    Set<String> passed = new HashSet<>(repo.findPassedItemsOnVersion(batchKey, current.version()));
    if (!passed.containsAll(required)) {
        throw ApiException.unprocessable("必做检验项未在当前成分版本 v" + current.version() + " 上全部重新通过，不能批准");
    }
    boolean actorInspected = repo.findTests(batchKey).stream().anyMatch(t -> t.inspector().equals(actor));
    if (actorInspected) throw unprocessable(...);
    List<ApprovalRow> all = repo.findApprovals(batchKey);
    List<ApprovalRow> postRisk = all.stream().filter(a -> a.id() > risk.approvalMarker()).toList();
    String now = now();
    int seq = all.size() + 1;
    BatchStatus newStatus;
    if (postRisk.isEmpty()) {
        newStatus = BatchStatus.ALLERGEN_RISK;
    } else {
        ApprovalRow first = postRisk.get(0);
        if (first.role().equals(role.name())) throw conflict("角色 ... 已在风险后批准过，需要另一种角色");
        if (first.actorId().equals(actor)) throw conflict("两个批准人必须不同");
        assertCompositionGate(batchKey);
        newStatus = BatchStatus.RELEASED;
        repo.clearRisk(batchKey, now);
    }
    repo.insertApproval(new ApprovalRow(0L, batchKey, req.commandKey(), actor, role.name(), seq, now));
    repo.updateStatus(batchKey, newStatus.name());
    return new StoredResponse(201, toJson(new ApprovalResponse(batchKey, actor, role, seq, newStatus, Instant.parse(now))));
}
