        assertEquals(1, (first == 201 ? 1 : 0) + (second == 201 ? 1 : 0),
                "并发同版本修订恰一个成功: " + first + "/" + second);
        assertTrue(first == 409 || second == 409);
        assertEquals(2, compositions(batch).size(), "仅胜出版本落库");
